from typing import List

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def createTree(parent: List[int], N: int) -> TreeNode:
    nodes = [TreeNode(i) for i in range(N)]
    root = None
    for i in range(N):
        if parent[i] == -1:
            root = nodes[i]
        else:
            p = nodes[parent[i]]
            if p.left is None:
                p.left = nodes[i]
            else:
                p.right = nodes[i]
    return root
